//! Connected S07 regression: real preparation/token/ffmpeg, no live planner/media.
use serde_json::{json,Value};
use std::{fs,path::Path,process::Command};
use workbench_host::{ctx::HostCtx,director,pending,session,workflow};
use workflow::{import,state::{ProjectState,JobStatus},post};
struct Guard;impl Drop for Guard{fn drop(&mut self){pending::cancel_all();session::close();}}
fn ok(c:&mut Command)->Vec<u8>{let p=c.output().unwrap();assert!(p.status.success(),"{c:?}: {}",String::from_utf8_lossy(&p.stderr));p.stdout}
fn read(r:&Path)->ProjectState{ProjectState::from_json(&fs::read_to_string(r.join("Preproduction/workflow_state.json")).unwrap()).unwrap()}
fn save(r:&Path,s:&ProjectState){import::persist_state(r,s).unwrap();}
fn fixture(r:&Path){
 for d in ["Preproduction","Scripts","Scene_Prompts/Scene1","Scenes/Scene1/Cut1","Scenes/Scene1/Cut2"]{fs::create_dir_all(r.join(d)).unwrap();}
 fs::write(r.join("Scripts/script.md"),"# Scene 1 — S07\n\n- **Action:** Blue and gold.\n").unwrap();
 fs::write(r.join("prod.md"),"### Scene 1\n```yaml\ntransition_in: cut\ntransition_out: cut\nspeech:\n  mode: none\n```\n### Scene 2\n```yaml\ntransition_in: cut\ntransition_out: cut\nspeech:\n  mode: none\n```\n").unwrap();
 for (i,color) in [(1,"blue"),(2,"gold")]{ok(Command::new("ffmpeg").args(["-v","error","-f","lavfi","-i",&format!("color=c={color}:s=160x90:r=24:d=2"),"-c:v","libx264","-threads","1","-pix_fmt","yuv420p"]).arg(r.join(format!("Scenes/Scene1/Cut{i}/take.mp4"))));fs::write(r.join(format!("Scene_Prompts/Scene1/Cut{i}.md")),format!("```yaml\nsource_scene: 1\ncut: {i}\ntitle: Shot {i}\nscene_type: b_roll\nspeech:\n  mode: none\nprompt: color {color}\n```\n")).unwrap();}
 let s:ProjectState=serde_json::from_value(json!({"version":2,"project_name":"S07 regression","settings":{"aspect_ratio":"9:16"},"profile":{"recipe":"narrative_dialogue","resolution":"1080x1920","aspect_ratios":["9:16"],"deliverables":[{"id":"review","name":"Review","resolution":"1080x1920","aspect_ratio":"9:16"}]},"assets":([1,2].map(|i|json!({"id":format!("take-{i}"),"path":format!("Scenes/Scene1/Cut{i}/take.mp4"),"role":"video_take","status":"present","scene_id":1,"cut_id":{"source_scene":1,"cut":i}}))),"scenes":[{"id":1,"stable_id":"scene-1","title":"S07","cuts":([1,2].map(|i|json!({"id":{"source_scene":1,"cut":i},"stable_id":format!("shot-{i}"),"source_origin":{"source_scene":1,"cut":i},"production_note_path":format!("Scene_Prompts/Scene1/Cut{i}.md"),"sketch":{"title":format!("Shot{i}"),"shot_role":"insert"},"visual_source":{"strategy":"no_start_frame"},"takes":[{"id":format!("take-{i}"),"path":format!("Scenes/Scene1/Cut{i}/take.mp4"),"status":"selected"}],"selected_take":format!("take-{i}")}))),"animatic":{"id":"anim","approved":true,"shots":([2,1].map(|i|json!({"id":format!("anim-{i}"),"cut_id":{"source_scene":1,"cut":i},"duration_seconds":2,"trim_in_seconds":0.25,"trim_out_seconds":0.25,"transition":if i==2{"dissolve"}else{"cut"}})))}}]})).unwrap();save(r,&s);
}
fn token(v:&Value)->String{v["pendingAction"].as_str().unwrap().split(pending::APPROVE_TOKEN_PREFIX).nth(1).unwrap().split("]]").next().unwrap().into()}
#[test]
fn s07_real_surface_assembly_and_strict_qc_contract(){
 let dir=tempfile::tempdir().unwrap();let root=dir.path().join("project");fs::create_dir(&root).unwrap();fixture(&root);session::open(root.to_str().unwrap()).unwrap();let _g=Guard;let app=HostCtx::new(dir.path().join("settings"));let args=json!({"projectRoot":root,"sceneId":1});
 let prep=workflow::cmd_prepare_assemble_with_host(&app,&args).unwrap();let s=read(&root);let job=s.jobs.last().unwrap().clone();assert_eq!(job.status,JobStatus::Pending);let snapshot=job.assembly_snapshot.as_ref().unwrap();assert_eq!(snapshot[0].shot_id,"shot-2");assert_eq!(snapshot[0].transition,"dissolve");assert_eq!(snapshot[0].start_seconds,0.25);assert_eq!(snapshot[0].duration_seconds,1.5);
 // A distinct generic approval cannot relabel a reserved output with different effective trim semantics.
 for per_entry in [false,true] {
  let mut inputs=json!({"production_path":"prod.md","output_path":job.output_path,"trim":"custom","caption_mode":"none","fade_in":false,"fade_out":false,"scenes":snapshot.iter().map(|s|json!({"id":s.cut_label,"video":s.path,"start":s.start_seconds,"duration":s.duration_seconds,"transition_out":s.transition})).collect::<Vec<_>>()});
  if per_entry {inputs["scenes"][0]["trim"]=json!("handles");}else{inputs["trim"]=json!("handles");}
  let action=workbench_host::director_actions::DirectorAction{action:workbench_host::director_actions::ActionKind::RunSpecialist,specialist:Some("assemble".into()),inputs:inputs.as_object().unwrap().clone(),message:None,op:None,path:None};
  let validated=workbench_host::director_actions::validate_action(action,Some(root.to_str().unwrap())).unwrap();let called=std::cell::Cell::new(false);
  let refusal=workflow::assembly_jobs::with_validated_assembly_job(&root,&validated,||{called.set(true);Err("must never run".into())});
  assert!(!called.get(),"effective trim override reached reserved assembly dispatch");assert!(refusal.is_err());assert_eq!(read(&root).jobs[0].status,JobStatus::Pending);
 }
 assert!(workflow::cmd_prepare_assemble_with_host(&app,&args).is_err());assert_eq!(read(&root).jobs.len(),1);
 let output=root.join(job.output_path.as_ref().unwrap());fs::create_dir_all(output.parent().unwrap()).unwrap();fs::copy(root.join("Scenes/Scene1/Cut1/take.mp4"),&output).unwrap();let refreshed=import::load_state(&root).unwrap();assert_eq!(refreshed.jobs[0].status,JobStatus::Pending);assert!(refreshed.scene(1).unwrap().post.as_ref().is_none_or(|p|p.versions.is_empty()));fs::remove_file(&output).unwrap();
 let result=director::director_approve(app.clone(),token(&prep)).unwrap();assert!(result.tool_events.iter().any(|e|e=="approve:assemble"),"{result:?}");let s=import::load_state(&root).unwrap();assert_eq!(s.jobs[0].status,JobStatus::Completed);assert!(s.jobs[0].completed_at.is_some());assert!(!s.jobs[0].output_asset_ids.is_empty());let v=s.scene(1).unwrap().post.as_ref().unwrap().versions.last().unwrap();assert_eq!(v.shots[0].shot_id,"shot-2");assert_eq!(v.assembly_snapshot.as_ref(),Some(snapshot));
 let probe:Value=serde_json::from_slice(&ok(Command::new("ffprobe").args(["-v","error","-show_format","-of","json"]).arg(&output))).unwrap();let duration=probe["format"]["duration"].as_str().unwrap().parse::<f64>().unwrap();assert!((duration-2.65).abs()<0.15,"{duration}");let rgb=ok(Command::new("ffmpeg").args(["-v","error","-i"]).arg(&output).args(["-vf","scale=1:1","-pix_fmt","rgb24","-f","rawvideo","-"]));assert!(rgb[0]>60&&rgb[1]>40&&rgb[2]<20,"{:?}",&rgb[..3]);assert!(rgb[rgb.len()-1]>60&&rgb[rgb.len()-3]<20);assert!(rgb.chunks_exact(3).any(|p|p[0]>20&&p[2]>20),"dissolve blend absent");let bytes=fs::read(&output).unwrap();assert!(director::director_approve(app.clone(),token(&prep)).is_err());assert_eq!(bytes,fs::read(&output).unwrap());
 // Fast-start MP4 headers can remain valid after payload truncation: require a full decode.
 let mut corrupt_state=read(&root);fs::write(&output,&bytes[..bytes.len()/2]).unwrap();let partial=post::check_deliverable(&mut corrupt_state,1,"review",&root).unwrap();fs::write(&output,&bytes).unwrap();assert!(!partial.passed,"truncated video payload falsely passed from its valid header");
 let mut s=read(&root);let pass=post::check_deliverable(&mut s,1,"review",&root).unwrap();assert!(pass.passed,"{:?}",pass);let baseline=s.clone();
 // Only one variable changes; good real media remains valid in every case.
 for case in ["same-id-new-path","same-path-new-id","duplicate","extra","empty","no-snapshot","trim","order","transition","no-assembly"]{let mut changed=baseline.clone();let scene=changed.scene_mut(1,"S07");match case{"same-id-new-path"=>scene.cuts[0].takes[0].path="new.mp4".into(),"same-path-new-id"=>{scene.cuts[0].takes[0].id="new-id".into();scene.cuts[0].selected_take=Some("new-id".into());},"duplicate"=>{let p=scene.post.as_mut().unwrap();p.versions[0].shots[1]=p.versions[0].shots[0].clone();},"extra"=>{let p=scene.post.as_mut().unwrap();let extra=p.versions[0].shots[0].clone();p.versions[0].shots.push(extra);},"empty"=>{scene.cuts.clear();let p=scene.post.as_mut().unwrap();p.versions[0].shots.clear();p.versions[0].assembly_snapshot=Some(vec![]);},"no-snapshot"=>scene.post.as_mut().unwrap().versions[0].assembly_snapshot=None,"trim"=>scene.animatic.as_mut().unwrap().shots[0].trim_in_seconds=Some(0.1),"order"=>scene.animatic.as_mut().unwrap().shots.reverse(),"transition"=>scene.animatic.as_mut().unwrap().shots[0].transition=Some(workflow::state::SequenceTransition::Cut),"no-assembly"=>scene.post.as_mut().unwrap().versions[0].assembly_path=None,_=>unreachable!()};let check=post::check_deliverable(&mut changed,1,"review",&root).unwrap();assert!(!check.passed,"{case} falsely passed");}
 // Matching completed plan may be reused; changed current inputs may not inherit output.
 let mut same=baseline.clone();let id=post::mark_cut_version(&mut same,1).unwrap();assert!(same.scene(1).unwrap().post.as_ref().unwrap().versions.iter().find(|v|v.id==id).unwrap().assembly_path.is_some());let mut changed=baseline.clone();changed.scene_mut(1,"S07").animatic.as_mut().unwrap().shots.reverse();let id=post::mark_cut_version(&mut changed,1).unwrap();assert!(changed.scene(1).unwrap().post.as_ref().unwrap().versions.iter().find(|v|v.id==id).unwrap().assembly_path.is_none());
 // Real boundary consumer, not merely testing path policy helper.
 for raw in [dir.path().join("outside.mp4").to_string_lossy().to_string(),"../outside.mp4".into(),"outside-link.mp4".into()]{fs::write(dir.path().join("outside.mp4"),b"outside untouched").unwrap();let link=root.join("outside-link.mp4");if !link.exists(){std::os::unix::fs::symlink(dir.path().join("outside.mp4"),&link).unwrap();}let mut s=baseline.clone();s.scene_mut(1,"S07").post.as_mut().unwrap().versions[0].assembly_path=Some(raw);assert!(post::check_deliverable(&mut s,1,"review",&root).is_err());assert_eq!(fs::read(dir.path().join("outside.mp4")).unwrap(),b"outside untouched");}
 // Source/output bytes cannot prove a successful new dispatch when malformed.
 let mut s=baseline.clone();s.jobs.clear();s.scene_mut(1,"S07").post=None;save(&root,&s);fs::remove_file(&output).unwrap();let p=workflow::cmd_prepare_assemble_with_host(&app,&args).unwrap();let pending=read(&root).jobs[0].clone();let result=workflow::assembly_jobs::with_assembly_job(&root,pending.output_path.as_ref().unwrap(),||{fs::write(&output,b"partial-not-a-movie").unwrap();Ok("pretended adapter success".into())});assert!(result.is_err(),"malformed bytes accepted as successful assembly");assert_eq!(read(&root).jobs[0].status,JobStatus::Failed);pending::cancel_all();let _=p;
 // A cleared native transition must override conflicting legacy production metadata.
 pending::cancel_all();let mut cleared=read(&root);cleared.jobs.clear();cleared.scene_mut(1,"S07").post=None;cleared.scene_mut(1,"S07").animatic.as_mut().unwrap().shots[0].transition=None;save(&root,&cleared);
 fs::write(root.join("prod.md"),"### Scene 1\n```yaml\ntransition_in: cut\ntransition_out: cut\nspeech:\n  mode: none\n```\n### Scene 2\n```yaml\ntransition_in: cut\ntransition_out: dissolve\nspeech:\n  mode: none\n```\n").unwrap();
 let cleared_prep=workflow::cmd_prepare_assemble_with_host(&app,&args).unwrap();let cleared_job=read(&root).jobs[0].clone();{
 let saved=cleared_job.assembly_snapshot.as_ref().unwrap();let mut inputs=json!({"production_path":"prod.md","output_path":cleared_job.output_path,"trim":"custom","caption_mode":"none","fade_in":false,"fade_out":false,"scenes":saved.iter().map(|s|json!({"id":s.cut_label,"video":s.path,"start":s.start_seconds,"duration":s.duration_seconds,"transition_out":s.transition})).collect::<Vec<_>>()});inputs["scenes"][0].as_object_mut().unwrap().remove("transition_out");
 let action=workbench_host::director_actions::DirectorAction{action:workbench_host::director_actions::ActionKind::RunSpecialist,specialist:Some("assemble".into()),inputs:inputs.as_object().unwrap().clone(),message:None,op:None,path:None};let validated=workbench_host::director_actions::validate_action(action,Some(root.to_str().unwrap())).unwrap();let called=std::cell::Cell::new(false);let refusal=workflow::assembly_jobs::with_validated_assembly_job(&root,&validated,||{called.set(true);Err("must never run".into())});assert!(!called.get(),"omitted transition inherited legacy metadata through reserved binding");assert!(refusal.is_err());assert_eq!(read(&root).jobs[0].status,JobStatus::Pending);
 } 
 let cleared_result=director::director_approve(app.clone(),token(&cleared_prep)).unwrap();assert_eq!(read(&root).jobs[0].status,JobStatus::Completed,"{cleared_result:?}");let movie=root.join(cleared_job.output_path.as_ref().unwrap());let probe:Value=serde_json::from_slice(&ok(Command::new("ffprobe").args(["-v","error","-show_format","-of","json"]).arg(&movie))).unwrap();let secs=probe["format"]["duration"].as_str().unwrap().parse::<f64>().unwrap();assert!((secs-3.0).abs()<0.15,"cleared transition inherited a dissolve: {secs}");
 // A real FFmpeg execution error settles the exact prepared job instead of leaving it Pending.
 let failed_prep=workflow::cmd_prepare_assemble_with_host(&app,&args).unwrap();let failed_id=read(&root).jobs.last().unwrap().id.clone();let work=root.join("Final/work");if work.is_dir(){fs::remove_dir_all(&work).unwrap();}fs::write(&work,b"task-owned output-work fault").unwrap();let failed_result=director::director_approve(app.clone(),token(&failed_prep));let after=read(&root);let failed=after.jobs.iter().find(|j|j.id==failed_id).unwrap();assert_eq!(failed.status,JobStatus::Failed,"{failed_result:?}");assert!(failed.completed_at.is_some());assert!(!root.join(failed.output_path.as_ref().unwrap()).is_file());fs::remove_file(&work).unwrap();
 eprintln!("S07 actual native approval produced {duration:.6}s gold→blue dissolve; exact snapshot/QC/provenance/replay cases passed");
}
